SET NAMES utf8mb4;
-- Clean database import; no passwords or demo records.
CREATE TABLE admin_users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL,
 role ENUM('super_admin','admin') NOT NULL DEFAULT 'admin', active TINYINT(1) NOT NULL DEFAULT 1, auth_version INT UNSIGNED NOT NULL DEFAULT 1,last_login_at DATETIME NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(role,active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE clients (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40) NOT NULL DEFAULT '',alternative_contact VARCHAR(255) NOT NULL DEFAULT '',area VARCHAR(160) NOT NULL DEFAULT '',address TEXT NULL,status ENUM('New','Active','Inactive','Archived') NOT NULL DEFAULT 'New',version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(email),INDEX(status,created_at),INDEX(full_name),INDEX(area)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE client_requests (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,role ENUM('Nanny','Domestic','Night Nurse','Housekeeper','To Confirm') NOT NULL,
 status ENUM('New','Reviewing','Brief Confirmed','Candidate Search','Candidates Presented','Placement Pending','Placement Confirmed','Closed','Archived') NOT NULL DEFAULT 'New',desired_start_date DATE NULL,details_json LONGTEXT NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id),INDEX(status,created_at),INDEX(role,status),INDEX(desired_start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE candidate_applications (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40) NOT NULL,area VARCHAR(160) NOT NULL,roles_json TEXT NOT NULL,details_json LONGTEXT NOT NULL,status ENUM('New','Reviewing','Contacted','Verification Required','Approved','Rejected','Archived') NOT NULL DEFAULT 'New',version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,created_at),INDEX(email),INDEX(full_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE candidates (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL UNIQUE,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40) NOT NULL,area VARCHAR(160) NOT NULL,experience TEXT NULL,languages VARCHAR(255) NOT NULL DEFAULT '',availability VARCHAR(160) NOT NULL DEFAULT '',living_preference ENUM('','Live-in','Live-out','Either') NOT NULL DEFAULT '',drivers_license ENUM('Unknown','Yes','No') NOT NULL DEFAULT 'Unknown',own_vehicle ENUM('Unknown','Yes','No') NOT NULL DEFAULT 'Unknown',first_aid ENUM('Unknown','Yes','No','Expired') NOT NULL DEFAULT 'Unknown',references_available ENUM('Unknown','Yes','No','Some') NOT NULL DEFAULT 'Unknown',status ENUM('Available','Being Considered','Placement Pending','Placed','Unavailable','Inactive','Archived') NOT NULL DEFAULT 'Available',version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES candidate_applications(id),INDEX(status,area),INDEX(email),INDEX(full_name),INDEX(availability)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE candidate_roles (candidate_id BIGINT UNSIGNED NOT NULL,role ENUM('Nanny','Domestic','Night Nurse','Housekeeper') NOT NULL,PRIMARY KEY(candidate_id,role),INDEX(role),FOREIGN KEY(candidate_id) REFERENCES candidates(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE client_candidate_matches (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_request_id BIGINT UNSIGNED NOT NULL,candidate_id BIGINT UNSIGNED NOT NULL,status ENUM('Considering','Contacted','Presented to Client','Interview / Discussion','Not Suitable','Selected') NOT NULL DEFAULT 'Considering',created_by BIGINT UNSIGNED NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(client_request_id,candidate_id),FOREIGN KEY(client_request_id) REFERENCES client_requests(id),FOREIGN KEY(candidate_id) REFERENCES candidates(id),FOREIGN KEY(created_by) REFERENCES admin_users(id),INDEX(status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE placements (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_request_id BIGINT UNSIGNED NOT NULL,candidate_id BIGINT UNSIGNED NOT NULL,placement_type ENUM('Direct Placement','Chore Payroll') NOT NULL DEFAULT 'Direct Placement',status ENUM('New','Candidate Selected','Agreement Pending','Confirmed','Active','Completed','Cancelled','Archived') NOT NULL DEFAULT 'New',start_date DATE NULL,version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(client_request_id,candidate_id),FOREIGN KEY(client_request_id) REFERENCES client_requests(id),FOREIGN KEY(candidate_id) REFERENCES candidates(id),INDEX(status,created_at),INDEX(placement_type),INDEX(start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE enquiries (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40) NOT NULL DEFAULT '',enquiry_type VARCHAR(60) NOT NULL,subject VARCHAR(255) NOT NULL,message TEXT NOT NULL,status ENUM('New','Read','Responded','Closed','Archived') NOT NULL DEFAULT 'New',version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,created_at),INDEX(full_name),INDEX(email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE notes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NULL,request_id BIGINT UNSIGNED NULL,candidate_id BIGINT UNSIGNED NULL,application_id BIGINT UNSIGNED NULL,placement_id BIGINT UNSIGNED NULL,enquiry_id BIGINT UNSIGNED NULL,admin_user_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(request_id) REFERENCES client_requests(id),FOREIGN KEY(candidate_id) REFERENCES candidates(id),FOREIGN KEY(application_id) REFERENCES candidate_applications(id),FOREIGN KEY(placement_id) REFERENCES placements(id),FOREIGN KEY(enquiry_id) REFERENCES enquiries(id),FOREIGN KEY(admin_user_id) REFERENCES admin_users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE documents (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,candidate_id BIGINT UNSIGNED NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,document_type ENUM('CV','ID','Passport','Certificate','First Aid','Reference','Driver licence','Other') NOT NULL,original_name VARCHAR(190) NOT NULL,stored_name CHAR(64) NOT NULL UNIQUE,mime_type VARCHAR(80) NOT NULL,size_bytes INT UNSIGNED NOT NULL,archived TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(candidate_id) REFERENCES candidates(id),FOREIGN KEY(uploaded_by) REFERENCES admin_users(id),INDEX(candidate_id,archived)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(40) NOT NULL,entity_id BIGINT UNSIGNED NULL,ip_hash CHAR(64) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_user_id) REFERENCES admin_users(id),INDEX(created_at),INDEX(entity_type,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_type VARCHAR(40) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,old_status VARCHAR(60) NULL,new_status VARCHAR(60) NOT NULL,admin_user_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_user_id) REFERENCES admin_users(id),INDEX(entity_type,entity_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_user_id) REFERENCES admin_users(id),INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE system_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO system_settings(setting_key,setting_value) VALUES ('notifications_enabled','1'),('business_name','The Chore Facilitator');
CREATE TABLE notification_queue (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(40) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,attempts INT UNSIGNED NOT NULL DEFAULT 0,sent_at DATETIME NULL,available_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(sent_at,available_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE submission_receipts (idempotency_hash CHAR(64) PRIMARY KEY,form_type VARCHAR(20) NOT NULL,entity_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
